from collections import deque
from itertools import combinations

def get_radius(n, adj):
    # BFS from each node
    ecc = []
    for s in range(n):
        dist = [-1]*n
        dist[s] = 0
        q = deque([s])
        while q:
            u = q.popleft()
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    q.append(v)
        if any(d == -1 for d in dist):
            return None # disconnected
        ecc.append(max(dist))
    return min(ecc)

def get_gamma_t(n, adj):
    for k in range(2, n + 1):
        for S in combinations(range(n), k):
            S_set = set(S)
            if all(any(nbr in S_set for nbr in adj[v]) for v in range(n)):
                return k
    return None

# Test on paths and cycles up to n=30
for n in range(2, 31):
    # Path P_n
    adj_path = [[] for _ in range(n)]
    for i in range(n-1):
        adj_path[i].append(i+1)
        adj_path[i+1].append(i)
    r = get_radius(n, adj_path)
    g = get_gamma_t(n, adj_path)
    if r > g:
        print(f'Path P_{n}: rad={r} > gamma_t={g}')
    # Cycle C_n
    adj_cycle = [list(l) for l in adj_path]
    adj_cycle[0].append(n-1)
    adj_cycle[n-1].append(0)
    r = get_radius(n, adj_cycle)
    g = get_gamma_t(n, adj_cycle)
    if r > g:
        print(f'Cycle C_{n}: rad={r} > gamma_t={g}')
print('Done checking paths and cycles.')
